TOP_SUITE_DETAILS = (
    '<p>Tester: Rasan soran (Member 5, E). SECJ3343 Project 1, TaskFlow main@5133a6c. '
    'Scope: reload persistence; storage recovery/failure; warning behavior; navigation/title; responsive sidebar; '
    'dialog focus/name; toast timing/semantics. A owns creation/text limits/draft cancellation, B editing/deletion, '
    'C enums/dates/status/counts, D querying. Shared actions are setup only.</p>'
    '<p>Basis: README.md Storage, Requirements traceability, Behaviour notes and Exact messages, plus implementing '
    'functions cited by each code-derived requirement. Cases are designs, initially Not Run; no execution or peer review claimed.</p>'
    '<p>Use a disposable Chrome profile at http://localhost:5173. Only seed/remove taskflow_tasks and '
    'taskflow_tasks_backup in that profile. Never clear personal browser data. For storage functions inaccessible '
    'through normal UI, cases marked UNIT HARNESS use DevTools Console on Vite, dynamically import /src/utils/storage.js, '
    'replace window.localStorage with a stub, and call loadTasks/saveTasks/resetStorage directly. This is a unit harness, '
    'not browser-level fault injection. To simulate failed UI writes without reload, patch '
    'Storage.prototype.setItem to throw a QuotaExceededError before the action; use the disposable profile. '
    'For storage fixtures define const validTask=(id,o={})=&gt;({id,title:\"Task \"+id,description:\"\",priority:\"Medium\",'
    'status:\"To Do\",dueDate:\"\",createdAt:\"2026-01-02T03:04:05.000Z\",updatedAt:\"2026-01-02T03:04:05.000Z\",...o}); '
    'const seedTasks=a=&gt;localStorage.setItem(\"taskflow_tasks\",JSON.stringify(a));. '
    'To inspect normalized loader objects use const m=await import(\"/src/utils/storage.js\"); console.log(m.loadTasks().tasks). '
    'For read faults use UNIT HARNESS: const m=await import(\"/src/utils/storage.js\"); '
    'Object.defineProperty(window,\"localStorage\",{configurable:true,value:{getItem(){throw Error(\"blocked\")},'
    'setItem(){throw Error(\"blocked\")},removeItem(){throw Error(\"blocked\")}}}); console.log(m.loadTasks());. '
    'For write fault on live UI: Storage.prototype.setItem=function(){throw new DOMException(\"blocked\",\"QuotaExceededError\")}. '
    'Restore only by closing the disposable profile. Toast target is 3000ms; accept manual timing from 2700 through 3800ms.</p>'
)

def req(rid, title, rule, code):
    return (rid, title, rule + ' Sources: README.md (Storage / Behaviour notes / Exact messages); ' + code + '; baseline main@5133a6c.')

